82	// WithDistillPassLock is the cross-process guard against two distill passes
83	// spending agent tokens on the same sessions at once. `setup` creates exactly
84	// that race: it spawns the detached backfill AND installs a watcher whose first
85	// tick distills immediately. The brain write lock does not help — it only wraps
86	// the flush at the END of a pass, so both processes sail through the expensive
87	// agent calls first and only then serialize on writing the identical facts.
88	//
89	// Two properties matter, and both differ from the other brain locks:
90	//
91	//   - it is held for the WHOLE pass, not just the write, because the token spend
92	//     is the resource being protected;
93	//   - it is TRY-only. A second comer must skip cleanly, not queue behind an
94	//     hours-long backfill and then re-spend on the sessions that backfill just
95	//     finished. onBusy reports the skip; the pass returns nil, because "someone
96	//     else is already doing this" is a success for the caller.
97	func WithDistillPassLock(brainDir string, onBusy func(), fn func() error) error {
98		if err := base.RejectSymlinkedBrainRoot(brainDir); err != nil {
99			return err
100		}
101		if err := base.RejectExistingSymlinkPathComponents(brainDir, BrainLockDirName); err != nil {
102			return err
103		}
104		// timeout 0 = try once; AcquireFileLock reports contention as a timeout.
105		lock, err := AcquireFileLock(filepath.Join(brainDir, BrainLockDirName, BrainDistillLockName), "distill_pass_locked", 0)
106		if err != nil {
107			if errors.Is(err, ErrFileLockTimeout) {
108				if onBusy != nil {
109					onBusy()
110				}
111				return nil
112			}
113			return err
114		}
115		defer func() { _ = lock.Close() }()
116		return fn()
117	}
