100	func historyFTSIdentityFromIndex(index historyIndex) historyFTSIdentity {
101		// ONE key space with historyFTSIdentityFromSource: the payload fast path
102		// derives the identity from the manifest without loading index.json, so an
103		// index-derived key that differed (for example a generation-path hash)
104		// would never match the persisted store and would silently disable that
105		// path. The records fingerprint already discriminates two generations that
106		// share a GeneratedAt and a record count but not their rows, and it is
107		// populated from the manifest on load, so this stays O(1) in practice.
108		fingerprint := index.RecordsFingerprint
109		if !historystore.ValidSHA256(fingerprint) {
110			fingerprint = historystore.RecordsFingerprint(index.Records)
111		}
112		return historyFTSIdentity{
113			RecordsFingerprint: fingerprint,
114			RecordCount:        len(index.Records),
115		}
116	}
