118	func historyFTSIdentityFromSource(source *historySourceManifest) (historyFTSIdentity, bool) {
119		if source == nil || source.Records < 0 || !historystore.ValidSHA256(source.RecordsFingerprint) {
120			return historyFTSIdentity{}, false
121		}
122		return historyFTSIdentity{RecordsFingerprint: source.RecordsFingerprint, RecordCount: source.Records}, true
123	}
