125	// openHistoryFTS opens (and rebuilds if stale) the derived BM25 index. The index
126	// is keyed by a fingerprint of the history index it was built from, so a refresh
127	// that regenerates history/index.json triggers a clean rebuild here.
128	//
129	// Locking is double-checked: the fresh-index fast path opens WITHOUT the
130	// exclusive brain lock — queries vastly outnumber rebuilds, and taking the
131	// write lock on the read path would serialize every concurrent search and
132	// time out (10s) against any long-running writer. Only a stale/missing index
133	// takes the lock, re-checking freshness under it because another process may
134	// have rebuilt while we waited. Concurrent readers of the fresh index are
135	// safe: the store is WAL-mode SQLite with a busy timeout.
136	func openHistoryFTS(brainDir string, index historyIndex) (*sql.DB, error) {
137		identity := historyFTSIdentityFromIndex(index)
138		if db, err := openHistoryFTSIfFreshIdentity(brainDir, identity); err == nil && db != nil {
139			return db, nil
140		}
141		var db *sql.DB
142		err := brainstore.WithBrainWriteLock(brainDir, func() error {
143			var runErr error
144			db, runErr = openHistoryFTSLockedIdentity(brainDir, index, identity)
145			return runErr
146		})
147		return db, err
148	}
