151	// matches the current history index, (nil, nil) when it is stale or missing.
152	func openHistoryFTSIfFresh(brainDir string, index historyIndex) (*sql.DB, error) {
153		return openHistoryFTSIfFreshIdentity(brainDir, historyFTSIdentityFromIndex(index))
154	}
