9	// RetrievalPrivacyPolicy is the checked tombstone generation under which a
10	// response was assembled. Keeping the brain path beside the identity lets the
11	// same final writer cover single-repository, workspace, get, and brief output.
12	type RetrievalPrivacyPolicy struct {
13		BrainDir            string
14		Identity            string
15		RequireDerivedClean bool
16	}
17	
18	// CaptureRetrievalPrivacyPolicy records the checked tombstone identity for one
19	// Brain. Loading the full guard, not just the tombstone file, keeps capture
20	// failing on the same invalid durable-transaction state every read would.
21	func CaptureRetrievalPrivacyPolicy(brainDir string) (RetrievalPrivacyPolicy, error) {
22		guard, err := LoadSessionReadGuard(brainDir, nil)
23		if err != nil {
24			return RetrievalPrivacyPolicy{}, err
25		}
26		return RetrievalPrivacyPolicy{BrainDir: brainDir, Identity: guard.PolicyIdentity}, nil
27	}
28	
29	// RequireRetrievalPrivacyPolicyIdentity fails when the Brain's checked
30	// tombstone identity no longer matches the identity a response was assembled
31	// under.
32	func RequireRetrievalPrivacyPolicyIdentity(brainDir, expected string) error {
33		guard, err := LoadSessionReadGuard(brainDir, nil)
34		if err != nil {
35			return err
36		}
37		if guard.PolicyIdentity != expected {
38			return fmt.Errorf("%s: retrieval privacy policy changed during response assembly; retry the request", PrivacyDirtyCode)
39		}
40		return nil
41	}
42	
43	// WithLockedRetrievalPrivacyPolicies is the response linearization boundary.
44	// Tombstone mutations use the same per-Brain write lock. Locks are acquired in
45	// deterministic path order so a workspace response spanning several Brains
46	// cannot deadlock with another workspace response containing the same members.
47	// requireDerivedClean is the caller's derived-read gate, enforced for every
48	// policy that demands it while the locks are held.
49	func WithLockedRetrievalPrivacyPolicies(policies []RetrievalPrivacyPolicy, requireDerivedClean func(string) error, fn func() error) error {
50		unlock, err := AcquireRetrievalPrivacyPolicies(policies, requireDerivedClean)
51		if err != nil {
52			return err
53		}
54		defer unlock()
55		return fn()
56	}
57	
58	func AcquireRetrievalPrivacyPolicies(policies []RetrievalPrivacyPolicy, requireDerivedClean func(string) error) (func(), error) {
59		byBrain := make(map[string]string, len(policies))
60		derivedClean := make(map[string]bool, len(policies))
61		for _, policy := range policies {
62			if policy.BrainDir == "" {
63				continue
64			}
65			brainDir := filepath.Clean(policy.BrainDir)
66			if prior, exists := byBrain[brainDir]; exists && prior != policy.Identity {
67				return nil, fmt.Errorf("%s: response was assembled under conflicting privacy policies", PrivacyDirtyCode)
68			}
69			byBrain[brainDir] = policy.Identity
70			derivedClean[brainDir] = derivedClean[brainDir] || policy.RequireDerivedClean
71		}
72		brainDirs := make([]string, 0, len(byBrain))
73		for brainDir := range byBrain {
74			brainDirs = append(brainDirs, brainDir)
75		}
76		sort.Strings(brainDirs)
77		unlocks := make([]func(), 0, len(brainDirs))
78		for _, brainDir := range brainDirs {
79			unlock, err := AcquireBrainWriteLock(brainDir)
80			if err != nil {
81				for i := len(unlocks) - 1; i >= 0; i-- {
82					unlocks[i]()
83				}
84				return nil, err
85			}
86			unlocks = append(unlocks, unlock)
87		}
88		release := func() {
89			for i := len(unlocks) - 1; i >= 0; i-- {
90				unlocks[i]()
91			}
92		}
93		for _, brainDir := range brainDirs {
94			if err := RequireRetrievalPrivacyPolicyIdentity(brainDir, byBrain[brainDir]); err != nil {
95				release()
96				return nil, err
97			}
98			if derivedClean[brainDir] {
99				if err := requireDerivedClean(brainDir); err != nil {
100					release()
101					return nil, err
102				}
103			}
104		}
105		return release, nil
106	}
