383	// factsBranchIsReal reports whether a branch name still names something: a ref
384	// git knows, or a fact store this brain already holds. The second half matters
385	// because a merged feature branch is commonly deleted while its facts live on,
386	// and promoting those forward is the whole point of the command.
387	func factsBranchIsReal(ctx context.Context, opts Options, repoDir, brainDir, branch string) bool {
388		if factstore.BranchStoreExists(brainDir, branch) {
389			return true
390		}
391		return gitRefExists(ctx, opts.Runner, repoDir, "refs/heads/"+branch) ||
392			gitRefExists(ctx, opts.Runner, repoDir, "refs/remotes/origin/"+branch)
393	}
