395	// validateFactsPromoteEndpoints checks the two branch names promote was handed.
396	// Neither used to be checked at all, and each typo failed in its own quiet way:
397	//
398	//   - a bad --from loaded nothing (factstore.Load reads a missing store as an empty
399	//     branch) and reported "promoted 0 fact(s)" — the same success line a real
400	//     but empty source produces, so the user had no way to tell a typo from a
401	//     branch that genuinely had nothing to give;
402	//   - a bad --into was worse than quiet. factstore.Write creates the target store on
403	//     demand, so promote happily forked the fact set into a directory keyed to a
404	//     branch that does not exist. Nothing reads it back, no later command names
405	//     it, and no branch can ever reach it: the facts are gone while the command
406	//     reports success.
407	//
408	// So both endpoints must name something real, and --from must additionally have
409	// facts — "nothing to promote" is a distinct, stateable outcome, not a success.
410	func validateFactsPromoteEndpoints(ctx context.Context, opts Options, repoDir, brainDir, from, into string) error {
411		if !factsBranchIsReal(ctx, opts, repoDir, brainDir, from) {
412			return fmt.Errorf("--from %q is not a branch: git does not know it and this brain holds no memories for it", from)
413		}
414		if !factstore.BranchStoreExists(brainDir, from) {
415			return fmt.Errorf("--from %q has no memories to promote", from)
416		}
417		if !factsBranchIsReal(ctx, opts, repoDir, brainDir, into) {
418			return fmt.Errorf("--into %q is not a branch: git does not know it and this brain holds no memories for it; promoting into it would strand a memory store no branch can reach", into)
419		}
420		return nil
421	}
