11	// countFactProposals totals the pending proposals across the given branches.
12	func countFactProposals(brainDir string, branches []string) int {
13		total := 0
14		for _, branch := range branches {
15			if proposals, err := loadFactProposals(brainDir, branch); err == nil {
16				total += len(proposals)
17			}
18		}
19		return total
20	}
