33	// reclassifyAllFactBranches backfills the deterministic KIND/LOCUS onto every
34	// fact store (non-destructive: only fills facts missing a valid kind, while
35	// locus is always reconciled), collapses records that repeat an id within one
36	// file, and rebuilds the fact source manifest so by_kind stays accurate. No
37	// agent, no tokens. A no-op when no facts exist. Returns the number of facts
38	// changed (reclassified plus duplicates folded). Holds the brain write lock
39	// for the whole pass.
40	//
41	// This runs from `refresh` so a kind never goes stale: facts distilled before
42	// kind-storage, or any fact left without a valid kind, are repaired on the next
43	// refresh rather than needing a manual `facts reclassify`.
44	//
45	// The pass iterates store FILES, never record-branch buckets. An earlier
46	// version wrote factstore.LoadAllBranches buckets back through factstore.Write, and a
47	// bucket spans files: every main-stamped record the hosted pull had mirrored
48	// into a feature branch's store was concatenated into main's file, roughly
49	// doubling it on each refresh (COR-2220). The per-file dedup below is also the
50	// repair for stores that doubling already damaged — the copies carry the same
51	// id, so folding them through Upsert's merge rules loses nothing.
52	func reclassifyAllFactBranches(brainDir string, now time.Time) (int, error) {
53		changed := 0
54		err := brainstore.WithBrainWriteLock(brainDir, func() error {
55			byFile, err := factstore.LoadStoreFiles(brainDir)
56			if err != nil {
57				return err
58			}
59			if len(byFile) == 0 {
60				return nil
61			}
62			for dirName, facts := range byFile {
63				deduped, folded := dedupFactRecords(facts)
64				c := factstore.Reclassify(deduped, false)
65				if c == 0 && folded == 0 {
66					continue
67				}
68				if err := factstore.WriteStoreFile(brainDir, dirName, deduped); err != nil {
69					return err
70				}
71				changed += c + folded
72			}
73			// Refresh upgrades even an unchanged legacy store. Ordinary read
74			// commands remain read-only, including on read-only installations.
75			if err := factstore.MigrateRepository(brainDir); err != nil {
76				return err
77			}
78			return updateFactSourceManifestLocked(brainDir, now)
79		})
80		return changed, err
81	}
